/**
 * Writes test/fixtures/db/P02.sql — the populated M2 database later phases migrate forward from.
 *
 * The container work lives in `@flowledger/testkit` because module resolution follows the importing
 * file's location: a script here cannot see the testkit's container dependencies.
 *
 * Run: `pnpm build && node test/fixtures/db/generate-p02.mjs`
 */
import { writeFileSync } from 'node:fs';
import process from 'node:process';
import { join } from 'node:path';

import { generateP02Fixture } from '../../../packages/testkit/dist/fixtures/p02-fixture.js';

const OUTPUT = join(import.meta.dirname, 'P02.sql');

const { sql, database } = await generateP02Fixture();
process.stdout.write(`dumped ${database.name}\n`);

writeFileSync(
  OUTPUT,
  [
    '-- P02.sql — populated M2 database (generated by test/fixtures/db/generate-p02.mjs).',
    '-- Do not edit: regenerate with `pnpm build && node test/fixtures/db/generate-p02.mjs`.',
    '-- Later phases keep this file and add their own <phase>.sql beside it.',
    '',
    sql,
  ].join('\n'),
);
process.stdout.write(`wrote ${OUTPUT}\n`);
